using Aict.Core;
using Aict.Beta;
using Aict.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public class WindowQuotaTests {
    static RuleGroup Group(int start=1080,int end=1320)=>Samples.Quota() with{DailyQuota=TimeSpan.FromSeconds(60),DailyQuotaWindow=new(start,end)};
    static UsageLedger Used(RuleGroup g,int day=2,long seconds=60)=>new UsageLedger().Put(g.Id,new(2026,11,day),new(TimeSpan.FromSeconds(seconds).Ticks));
    static bool Blocked(RuleGroup g,UsageLedger ledger,DateTimeOffset at,bool healthy=true)=>RuleEngine.Evaluate(Samples.Policy(g),ledger,new("app.video"),new(at),healthy).Blocked;
    [TestMethod] public void ExhaustionOnlyBlocksInsideWindowWithHalfOpenEdges(){var g=Group();var l=Used(g);Assert.IsFalse(Blocked(g,l,Samples.At(2,17,59,59)));Assert.IsTrue(Blocked(g,l,Samples.At(2,18)));Assert.IsTrue(Blocked(g,l,Samples.At(2,21,59,59)));Assert.IsFalse(Blocked(g,l,Samples.At(2,22)));Assert.IsFalse(Blocked(g,l,Samples.At(3,18)));Assert.IsNull(RuleEngine.Evaluate(Samples.Policy(g),l,new("app.video"),new(Samples.At(2,23))).Groups.Single().QuotaRemaining);}
    [TestMethod] public void KnownUsageIsClippedToWindowStartAndEndAndIdleCutoff(){var g=Group();var p=Samples.Policy(g);var l=RuleEngine.Account(p,new(),new(Samples.At(2,17,59,30),TimeSpan.FromSeconds(60),new("app.video")));Assert.AreEqual(TimeSpan.FromSeconds(30).Ticks,l.Get(g.Id,new(2026,11,2)).KnownTicks);l=RuleEngine.Account(p,l,new(Samples.At(2,21,59,30),TimeSpan.FromSeconds(60),new("app.video")));Assert.AreEqual(TimeSpan.FromSeconds(60).Ticks,l.Get(g.Id,new(2026,11,2)).KnownTicks);var idle=RuleEngine.Account(p,new(),new(Samples.At(2,17,59,30),TimeSpan.FromSeconds(60),new("app.video"),IdleAtStart:TimeSpan.FromSeconds(45)));Assert.AreEqual(0L,idle.Get(g.Id,new(2026,11,2)).KnownTicks);}
    [TestMethod] public void CrossMidnightSharesStartingDateAndDoesNotResetAtMidnight(){var g=Group(1320,120);var p=Samples.Policy(g);var l=RuleEngine.Account(p,new(),new(Samples.At(2,23,59,30),TimeSpan.FromSeconds(60),new("app.video")));Assert.AreEqual(TimeSpan.FromSeconds(60).Ticks,l.Get(g.Id,new(2026,11,2)).KnownTicks);Assert.AreEqual(0L,l.Get(g.Id,new(2026,11,3)).KnownTicks);Assert.IsTrue(Blocked(g,l,Samples.At(3,0,30)));Assert.IsTrue(Blocked(g,l,Samples.At(3,1,59,59)));Assert.IsFalse(Blocked(g,l,Samples.At(3,2)));Assert.IsFalse(Blocked(g,l,Samples.At(3,22)));}
    [TestMethod] public void UnknownObservationsOnlyCensorOverlappingQuotaWindows(){var g=Group();var p=Samples.Policy(g);var l=RuleEngine.Account(p,new(),new(Samples.At(2,10),TimeSpan.FromHours(1),new("app.video"),ObservationKnown:false));Assert.AreEqual(0,l.Accounts.Count);l=RuleEngine.Account(p,l,new(Samples.At(2,17,59),TimeSpan.FromMinutes(2),new("app.video"),ObservationKnown:false));Assert.IsTrue(l.Get(g.Id,new(2026,11,2)).HasGap);Assert.IsTrue(Blocked(g,l,Samples.At(2,19)));Assert.IsFalse(Blocked(g,l,Samples.At(2,23),healthy:false));}
    [TestMethod] public void LongGapsAcrossSeveralDaysAreCensoredPerIntersectingPeriod(){var g=Group(1320,120);var l=RuleEngine.Account(Samples.Policy(g),new(),new(Samples.At(2,23),TimeSpan.FromDays(2),new("app.video"),ObservationKnown:false));Assert.IsTrue(l.Get(g.Id,new(2026,11,2)).HasGap);Assert.IsTrue(l.Get(g.Id,new(2026,11,3)).HasGap);Assert.IsTrue(l.Get(g.Id,new(2026,11,4)).HasGap);Assert.AreEqual(3,l.Accounts.Count);}
    [TestMethod] public void HardScheduleAndOtherGroupsRemainIndependentOfQuotaWindow(){var g=Group() with{Windows=[new(Weekdays.All,9*60,10*60)]};Assert.IsTrue(Blocked(g,new(),Samples.At(2,9,30)));Assert.IsFalse(Blocked(g,new(),Samples.At(2,12)));var other=g with{Id=Guid.NewGuid(),DailyQuota=null,DailyQuotaWindow=null,AlwaysBlock=true};Assert.IsTrue(RuleEngine.Evaluate(Samples.Policy(g) with{Groups=[g,other]},new(),new("app.video"),new(Samples.At(2,12))).Blocked);}
    [TestMethod] public void ScopeChangesWaitAndCarryUsageWithoutResettingAtNewDayKey(){var old=Group(1320,120);var next=old with{DailyQuotaWindow=new(0,1440)};var p=Samples.Policy(old) with{ChangeDelay=TimeSpan.FromSeconds(10)};var q=p with{Groups=[next]};var now=Samples.At(3,0,30);Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,q,now));Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,p with{Groups=[old with{DailyQuota=TimeSpan.FromSeconds(30)}]},now));var s=ChangeQueue.Submit(new(){Policy=p,Usage=Used(old),Clock=new(now,true)},q,new(now,true));s=s with{Pending=s.Pending! with{ApplyAtDeadline=true}};Assert.AreEqual(ApplyStatus.WaitingForDelay,ChangeQueue.TryApply(s,new(now.AddSeconds(9),true)).Status);var applied=ChangeQueue.TryApply(s,new(now.AddSeconds(10),true));Assert.AreEqual(ApplyStatus.Applied,applied.Status);Assert.AreEqual(TimeSpan.FromSeconds(60).Ticks,applied.Snapshot.Usage.Get(old.Id,new(2026,11,3)).KnownTicks);Assert.IsTrue(Blocked(next,applied.Snapshot.Usage,now));}
    [TestMethod] public void LegacyDailyBehaviorAndSerializationArePreserved(){var g=Samples.Quota();Assert.IsFalse(PolicyJson.Serialize(g).Contains("dailyQuotaWindow"));var l=Used(g);Assert.IsTrue(Blocked(g,l,Samples.At(2,23,59,59)));Assert.IsFalse(Blocked(g,l,Samples.At(3)));var copy=PolicyJson.Parse<RuleGroup>(PolicyJson.Serialize(Group(1320,120)));Assert.AreEqual(new QuotaWindow(1320,120),copy.DailyQuotaWindow);}
    [TestMethod] public void ZeroAllowanceAnd2400EndAreSupportedButInvalidWindowsRejected(){var g=Group(1080,1440) with{DailyQuota=TimeSpan.Zero};Assert.IsTrue(Blocked(g,new(),Samples.At(2,18)));Assert.IsFalse(Blocked(g,new(),Samples.At(3,0)));foreach(var window in new[]{new QuotaWindow(60,60),new(-1,120),new(1440,120),new(60,1441)})Assert.ThrowsExactly<ArgumentException>(()=>PolicyValidation.Validate(Samples.Policy(g with{DailyQuotaWindow=window})));Assert.ThrowsExactly<ArgumentException>(()=>PolicyValidation.Validate(Samples.Policy(g with{DailyQuota=null})));}
    [TestMethod] public void CsvNamesCurrentScopeAndPeriodStartingDate(){var g=Group(1320,120);var csv=UsageExport.ToCsv(Samples.Policy(g),Used(g));StringAssert.Contains(csv,"current_quota_window");StringAssert.Contains(csv,"2026-11-02");StringAssert.Contains(csv,"次日 02:00");}
    sealed class Clock:IClock {public string BootId=>"window";public long Uptime{get;set;}public long AwakeMilliseconds=>Uptime;public DateTimeOffset UtcNow{get;set;}=Samples.At(2,23,59,30);public void Add(int ms){Uptime+=ms;UtcNow=UtcNow.AddMilliseconds(ms);}}
    [TestMethod] public async Task BackendWebsitePlansAndStatusUseTheSameWindowAndSurviveRestart(){var c=new Clock();var g=Group(1320,120) with{ApplicationMode=TargetMode.None,ApplicationIds=[]};string folder=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")??Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string db=Path.Combine(folder,"engine.sqlite");var a=new Authority(StateRepository.CreateNew(db,Authority.Initial(c)),c,[]);var s=(await a.Handle(new())).Status!;Assert.IsTrue((await a.Handle(new(){Command=Command.SubmitPolicy,EditToken=s.EditToken,Policy=Samples.Policy(g)})).Ok);await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,false,0,"Edge")},true);string profile=new string('1',32);await a.Handle(new(){Command=Command.BrowserPulse,Browser=new("Edge",profile,(await a.Desired()).Web.Fingerprint,true,false,"video.example")},true);for(int i=0;i<60;i++){c.Add(1000);await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,false,0,"Edge")},true);await a.Handle(new(){Command=Command.BrowserPulse,Browser=new("Edge",profile,(await a.Desired()).Web.Fingerprint,true,false,"video.example")},true);}s=(await a.Handle(new())).Status!;Assert.AreEqual(TimeSpan.FromSeconds(60).Ticks,s.Usage.Single().UsedTicks);Assert.IsTrue(s.Usage.Single().QuotaWindowActive);Assert.AreEqual(1,(await a.Desired()).Web.Groups.Length);a.Dispose();using var restored=new Authority(StateRepository.OpenExisting(db),c,[]);s=(await restored.Handle(new())).Status!;Assert.AreEqual(TimeSpan.FromSeconds(60).Ticks,s.Usage.Single().UsedTicks);c.Add((int)(Samples.At(3,2)-c.UtcNow).TotalMilliseconds);var state=(await restored.Handle(new())).Status!;Assert.IsFalse(state.Usage.Single().QuotaWindowActive);Assert.IsTrue((await restored.Desired()).Web.Groups.IsEmpty);}
}
